import bisect

class Solution:
    def closestAcross(self, a: List[int], b: List[int]) -> int:
        best = abs(a[0] - b[0])
        for x in a:
            p = bisect.bisect_left(b, x)
            if p < len(b):
                best = min(best, b[p] - x)
            if p > 0:
                best = min(best, x - b[p - 1])
        return best

