class Solution {
    public int closestAcross(int[] a, int[] b) {
        long best = Math.abs((long) a[0] - b[0]);
        for (int x : a) {
            int lo = 0, hi = b.length;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (b[mid] < x) lo = mid + 1; else hi = mid; }
            if (lo < b.length) best = Math.min(best, (long) b[lo] - x);
            if (lo > 0) best = Math.min(best, (long) x - b[lo - 1]);
        }
        return (int) best;
    }
}

