class Solution:
    def closestAcross(self, a: List[int], b: List[int]) -> int:
        i = j = 0
        best = abs(a[0] - b[0])
        while i < len(a) and j < len(b):
            best = min(best, abs(a[i] - b[j]))
            if a[i] < b[j]:
                i += 1
            else:
                j += 1
        return best

