        int i = 0, j = 0;
        long best = Math.abs((long) a[0] - b[0]);
        while (i < a.length && j < b.length) {
            best = Math.min(best, Math.abs((long) a[i] - b[j]));
            if (a[i] < b[j]) i++;
            else j++;
        }
        return (int) best;
    }
}

