int closestAcross(int* a, int aSize, int* b, int bSize) {
    int i = 0, j = 0;
    long long best = llabs((long long) a[0] - b[0]);
    while (i < aSize && j < bSize) {
        long long d = llabs((long long) a[i] - b[j]);
        if (d < best) best = d;
        if (a[i] < b[j]) i++;
